import { z } from "zod"

import { isSafeLocalAssetPath } from "@/components/fable-ui/v2/asset-utils"
import {
  isSafeFableLinkHref,
  MAX_FABLE_HOST_LINKS,
  MAX_FABLE_LINK_HREF_CHARS,
  MAX_FABLE_RICH_CONTENT_BLOCKS,
  MAX_FABLE_RICH_CONTENT_CODE_CHARS,
  MAX_FABLE_RICH_CONTENT_ELEMENT_BYTES,
  MAX_FABLE_RICH_CONTENT_LIST_ITEMS,
  MAX_FABLE_RICH_CONTENT_SPANS,
  MAX_FABLE_RICH_CONTENT_TEXT_CHARS,
  MAX_FABLE_RICH_CONTENT_TOTAL_CHARS,
} from "./rich-content-utils"

const reservedIds = new Set(["__proto__", "prototype", "constructor"])

export const FableIdSchema = z
  .string()
  .min(1)
  .max(64)
  .regex(/^[A-Za-z0-9][A-Za-z0-9_-]*$/)
  .refine((value) => !reservedIds.has(value))

const shortText = (max: number) => z.string().trim().min(1).max(max)
const localeSchema = z
  .string()
  .max(32)
  .refine((locale) => {
    try {
      Intl.getCanonicalLocales(locale)
      return true
    } catch {
      return false
    }
  })
const gapSchema = z.union([
  z.literal(0),
  z.literal(1),
  z.literal(2),
  z.literal(3),
  z.literal(4),
  z.literal(6),
  z.literal(8),
])
const childrenSchema = z.array(FableIdSchema).max(24)
const leafChildrenSchema = z.array(FableIdSchema).max(0)

const textPropsSchema = z
  .object({
    content: z.string().max(2000),
    level: z.enum(["body", "heading", "caption"]),
  })
  .strict()

const richTextPropsSchema = z
  .object({
    spans: z
      .array(
        z
          .object({
            text: z.string().max(240),
            mark: z.enum(["plain", "strong", "emphasis", "code"]),
          })
          .strict()
      )
      .max(16),
  })
  .strict()

const richContentInlineSchema = z.discriminatedUnion("type", [
  z
    .object({
      type: z.literal("text"),
      text: z.string().max(MAX_FABLE_RICH_CONTENT_TEXT_CHARS),
      mark: z.enum(["plain", "strong", "emphasis", "code"]),
    })
    .strict(),
  z
    .object({
      type: z.literal("link"),
      linkId: FableIdSchema,
    })
    .strict(),
])

const richContentSpansSchema = z
  .array(richContentInlineSchema)
  .min(1)
  .max(MAX_FABLE_RICH_CONTENT_SPANS)

const richContentBlockSchema = z.discriminatedUnion("type", [
  z
    .object({
      type: z.literal("paragraph"),
      spans: richContentSpansSchema,
    })
    .strict(),
  z
    .object({
      type: z.literal("heading"),
      level: z.union([z.literal(2), z.literal(3)]),
      spans: richContentSpansSchema,
    })
    .strict(),
  z
    .object({
      type: z.literal("list"),
      ordered: z.boolean(),
      items: z
        .array(richContentSpansSchema)
        .min(1)
        .max(MAX_FABLE_RICH_CONTENT_LIST_ITEMS),
    })
    .strict(),
  z
    .object({
      type: z.literal("quote"),
      spans: richContentSpansSchema,
    })
    .strict(),
  z
    .object({
      type: z.literal("code"),
      code: z.string().min(1).max(MAX_FABLE_RICH_CONTENT_CODE_CHARS),
      language: z
        .string()
        .regex(/^[A-Za-z0-9+#.-]{1,24}$/)
        .optional(),
    })
    .strict(),
])

const richContentPropsSchema = z
  .object({
    blocks: z
      .array(richContentBlockSchema)
      .min(1)
      .max(MAX_FABLE_RICH_CONTENT_BLOCKS),
  })
  .strict()
  .superRefine((props, context) => {
    const totalChars = props.blocks.reduce((total, block) => {
      if (block.type === "code") return total + block.code.length
      const spans = block.type === "list" ? block.items.flat() : block.spans
      return (
        total +
        spans.reduce(
          (spanTotal, span) =>
            spanTotal + (span.type === "text" ? span.text.length : 0),
          0
        )
      )
    }, 0)

    if (totalChars > MAX_FABLE_RICH_CONTENT_TOTAL_CHARS) {
      context.addIssue({
        code: "custom",
        message: "rich_content_total_text_too_large",
        path: ["blocks"],
      })
    }
  })

const metricPropsSchema = z
  .object({
    resultId: FableIdSchema,
  })
  .strict()

const entityListPropsSchema = z
  .object({
    resultId: FableIdSchema,
    filterId: FableIdSchema.optional(),
  })
  .strict()

const chartPropsSchema = z
  .object({
    resultId: FableIdSchema,
  })
  .strict()

const filterPropsSchema = z
  .object({
    filterId: FableIdSchema,
  })
  .strict()

const mediaPropsSchema = z
  .object({
    assetId: FableIdSchema,
  })
  .strict()

const stackPropsSchema = z
  .object({
    direction: z.enum(["vertical", "horizontal"]),
    gap: gapSchema,
  })
  .strict()

const gridPropsSchema = z
  .object({
    columns: z.union([z.literal(1), z.literal(2), z.literal(3), z.literal(4)]),
    gap: gapSchema,
  })
  .strict()

const sectionPropsSchema = z
  .object({
    title: shortText(120).optional(),
    gap: gapSchema,
  })
  .strict()

const surfacePropsSchema = z
  .object({
    variant: z.enum(["plain", "outlined", "subtle"]),
    padding: gapSchema,
  })
  .strict()

const fableElementSchema = z.discriminatedUnion("type", [
  z
    .object({
      type: z.literal("Text"),
      props: textPropsSchema,
      children: leafChildrenSchema,
    })
    .strict(),
  z
    .object({
      type: z.literal("RichText"),
      props: richTextPropsSchema,
      children: leafChildrenSchema,
    })
    .strict(),
  z
    .object({
      type: z.literal("RichContent"),
      props: richContentPropsSchema,
      children: leafChildrenSchema,
    })
    .strict(),
  z
    .object({
      type: z.literal("Metric"),
      props: metricPropsSchema,
      children: leafChildrenSchema,
    })
    .strict(),
  z
    .object({
      type: z.literal("EntityList"),
      props: entityListPropsSchema,
      children: leafChildrenSchema,
    })
    .strict(),
  z
    .object({
      type: z.literal("Chart"),
      props: chartPropsSchema,
      children: leafChildrenSchema,
    })
    .strict(),
  z
    .object({
      type: z.literal("Filter"),
      props: filterPropsSchema,
      children: leafChildrenSchema,
    })
    .strict(),
  z
    .object({
      type: z.literal("Media"),
      props: mediaPropsSchema,
      children: leafChildrenSchema,
    })
    .strict(),
  z
    .object({
      type: z.literal("Stack"),
      props: stackPropsSchema,
      children: childrenSchema,
    })
    .strict(),
  z
    .object({
      type: z.literal("Grid"),
      props: gridPropsSchema,
      children: childrenSchema,
    })
    .strict(),
  z
    .object({
      type: z.literal("Section"),
      props: sectionPropsSchema,
      children: childrenSchema,
    })
    .strict(),
  z
    .object({
      type: z.literal("Surface"),
      props: surfacePropsSchema,
      children: childrenSchema,
    })
    .strict(),
])

export const FableElementSchema = fableElementSchema.superRefine(
  (element, context) => {
    if (element.type !== "RichContent") return

    const elementBytes = new TextEncoder().encode(
      JSON.stringify(element)
    ).byteLength
    if (elementBytes > MAX_FABLE_RICH_CONTENT_ELEMENT_BYTES) {
      context.addIssue({
        code: "custom",
        message: "rich_content_element_too_large",
        path: ["props", "blocks"],
      })
    }
  }
)

export const FableViewSpecSchema = z
  .object({
    root: FableIdSchema,
    elements: z.record(FableIdSchema, FableElementSchema),
  })
  .strict()

const metricResultSchema = z
  .object({
    kind: z.literal("metric"),
    label: shortText(120),
    value: z.number().finite(),
    format: z.enum(["number", "currency", "percent"]),
    currency: z
      .string()
      .regex(/^[A-Z]{3}$/)
      .optional(),
    unit: z.string().max(40).optional(),
    locale: localeSchema.optional(),
  })
  .strict()
  .refine(
    (result) => result.format !== "currency" || result.currency !== undefined
  )

const entityItemSchema = z
  .object({
    id: FableIdSchema,
    name: shortText(120),
    location: shortText(80),
    description: z.string().max(240),
    value: z.number().finite(),
    unit: z.string().max(40).optional(),
    changePercent: z.number().finite().optional(),
    filterValues: z.record(FableIdSchema, shortText(80)).optional(),
  })
  .strict()

const entityListResultSchema = z
  .object({
    kind: z.literal("entity-list"),
    label: shortText(120),
    valueLabel: shortText(80).optional(),
    locale: localeSchema.optional(),
    items: z.array(entityItemSchema).max(20),
  })
  .strict()
  .superRefine((result, context) => {
    const ids = new Set<string>()
    for (const item of result.items) {
      if (ids.has(item.id)) {
        context.addIssue({ code: "custom", message: "duplicate_entity_id" })
      }
      ids.add(item.id)
    }
  })

const chartResultSchema = z
  .object({
    kind: z.literal("chart"),
    label: shortText(120),
    points: z
      .array(
        z
          .object({
            label: shortText(40),
            value: z.number().finite(),
          })
          .strict()
      )
      .min(1)
      .max(12),
    format: z.enum(["number", "currency", "percent"]).default("number"),
    currency: z
      .string()
      .regex(/^[A-Z]{3}$/)
      .optional(),
    locale: localeSchema.optional(),
  })
  .strict()
  .refine(
    (result) => result.format !== "currency" || result.currency !== undefined
  )

const filterResultSchema = z
  .object({
    kind: z.literal("filter"),
    label: shortText(80),
    allValue: FableIdSchema,
    options: z
      .array(
        z
          .object({
            label: shortText(80),
            value: FableIdSchema,
          })
          .strict()
      )
      .min(1)
      .max(12),
  })
  .strict()
  .superRefine((filter, context) => {
    const values = new Set<string>()
    for (const option of filter.options) {
      if (values.has(option.value)) {
        context.addIssue({ code: "custom", message: "duplicate_filter_value" })
      }
      values.add(option.value)
    }
    if (!values.has(filter.allValue)) {
      context.addIssue({ code: "custom", message: "missing_all_filter_value" })
    }
  })

export const FableViewDataResultSchema = z.discriminatedUnion("kind", [
  metricResultSchema,
  entityListResultSchema,
  chartResultSchema,
  filterResultSchema,
])

export const FableViewDataSchema = z
  .record(FableIdSchema, FableViewDataResultSchema)
  .superRefine((results, context) => {
    if (Object.keys(results).length > 64) {
      context.addIssue({ code: "custom", message: "too_many_results" })
    }
  })

const hostAssetSchema = z
  .object({
    src: z.string().max(240),
    alt: z.string().max(200),
    decorative: z.boolean().default(false),
  })
  .strict()
  .refine((asset) => asset.decorative || asset.alt.trim().length > 0)

export const FableAssetCatalogSchema = z
  .record(FableIdSchema, hostAssetSchema)
  .superRefine((assets, context) => {
    if (Object.keys(assets).length > 24) {
      context.addIssue({ code: "custom", message: "too_many_assets" })
    }
    for (const [assetId, asset] of Object.entries(assets)) {
      if (!isSafeLocalAssetPath(asset.src)) {
        context.addIssue({
          code: "custom",
          message: "unsafe_asset_path",
          path: [assetId],
        })
      }
    }
  })

const hostLinkSchema = z
  .object({
    href: z.string().max(MAX_FABLE_LINK_HREF_CHARS).refine(isSafeFableLinkHref),
    label: shortText(120),
  })
  .strict()

export const FableLinkCatalogSchema = z
  .record(FableIdSchema, hostLinkSchema)
  .superRefine((links, context) => {
    if (Object.keys(links).length > MAX_FABLE_HOST_LINKS) {
      context.addIssue({ code: "custom", message: "too_many_host_links" })
    }
  })

export type FableElement = z.infer<typeof FableElementSchema>
export type FableViewSpec = z.infer<typeof FableViewSpecSchema>
export type FableViewDataResult = z.infer<typeof FableViewDataResultSchema>
export type FableViewData = z.infer<typeof FableViewDataSchema>
export type FableAssetCatalog = z.infer<typeof FableAssetCatalogSchema>
export type FableHostLinkCatalog = z.infer<typeof FableLinkCatalogSchema>
export type FableMetricResult = z.infer<typeof metricResultSchema>
export type FableEntityListResult = z.infer<typeof entityListResultSchema>
export type FableChartResult = z.infer<typeof chartResultSchema>
export type FableFilterResult = z.infer<typeof filterResultSchema>
export type FableEntityItem = z.infer<typeof entityItemSchema>

export type FableSpecValidation =
  { success: true; data: FableViewSpec } | { success: false; issues: string[] }

export function validateFableViewSpec(input: unknown): FableSpecValidation {
  const parsed = FableViewSpecSchema.safeParse(input)
  if (!parsed.success) {
    return { success: false, issues: ["invalid_component_schema"] }
  }

  const { root, elements } = parsed.data
  const elementIds = Object.keys(elements)
  if (elementIds.length === 0 || elementIds.length > 32) {
    return { success: false, issues: ["invalid_element_count"] }
  }
  if (!Object.hasOwn(elements, root)) {
    return { success: false, issues: ["root_not_found"] }
  }

  const visited = new Set<string>()
  const active = new Set<string>()
  const parentCount = new Map<string, number>()
  let issue: string | undefined

  const visit = (id: string, depth: number) => {
    if (issue) return
    if (depth > 6) {
      issue = "maximum_depth_exceeded"
      return
    }
    if (active.has(id)) {
      issue = "cyclic_tree"
      return
    }
    if (visited.has(id)) return

    const element = elements[id]
    if (!element) {
      issue = "missing_child"
      return
    }

    visited.add(id)
    active.add(id)
    for (const childId of element.children) {
      if (!Object.hasOwn(elements, childId)) {
        issue = "missing_child"
        break
      }
      const nextParentCount = (parentCount.get(childId) ?? 0) + 1
      parentCount.set(childId, nextParentCount)
      if (nextParentCount > 1) {
        issue = "multiple_parents"
        break
      }
      visit(childId, depth + 1)
    }
    active.delete(id)
  }

  visit(root, 1)
  if (issue) return { success: false, issues: [issue] }
  if (visited.size !== elementIds.length) {
    return { success: false, issues: ["orphaned_element"] }
  }

  return { success: true, data: parsed.data }
}

import { createSpecStreamCompiler } from "@json-render/core"
import { z } from "zod"

import {
  FableElementSchema,
  FableIdSchema,
  validateFableViewSpec,
  type FableElement,
  type FableViewSpec,
} from "./catalog"

const MAX_STREAM_BYTES = 64 * 1024
const MAX_PATCH_LINE_BYTES = 16 * 1024
const MAX_ELEMENTS = 32

const patchEnvelopeSchema = z.discriminatedUnion("op", [
  z
    .object({
      op: z.literal("add"),
      path: z.string().max(160),
      value: z.unknown(),
    })
    .strict(),
  z
    .object({
      op: z.literal("replace"),
      path: z.string().max(160),
      value: z.unknown(),
    })
    .strict(),
])

export interface FableStreamUpdate {
  spec: FableViewSpec | null
  acceptedPatches: number
  complete: boolean
  issue?: string
}

type CompilerState = {
  root?: unknown
  elements?: unknown
}

type SafePatch = {
  op: "add" | "replace"
  path: "/root"
  value: string
} | {
  op: "add" | "replace"
  path: `/elements/${string}`
  value: FableElement
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value)
}

function byteLength(value: string): number {
  return new TextEncoder().encode(value).byteLength
}

/**
 * Validates each JSONL patch before the third-party compiler sees it. Only a
 * root ID or one complete, strict Fable element can be added or replaced.
 */
export class FableSpecStream {
  private compiler = createSpecStreamCompiler<CompilerState>({})
  private lineBuffer = ""
  private totalBytes = 0
  private acceptedPatches = 0
  private lastValidSpec: FableViewSpec | null = null
  private issue: string | undefined
  private closed = false
  private complete = false

  push(chunk: string): FableStreamUpdate {
    if (this.closed) return this.closedSnapshot()

    this.totalBytes += byteLength(chunk)
    if (this.totalBytes > MAX_STREAM_BYTES) {
      return this.fail("stream_too_large")
    }

    this.lineBuffer += chunk
    if (byteLength(this.lineBuffer) > MAX_PATCH_LINE_BYTES && !this.lineBuffer.includes("\n")) {
      return this.fail("patch_line_too_large")
    }

    while (true) {
      const newline = this.lineBuffer.indexOf("\n")
      if (newline < 0) break

      const line = this.lineBuffer.slice(0, newline)
      this.lineBuffer = this.lineBuffer.slice(newline + 1)
      if (byteLength(line) > MAX_PATCH_LINE_BYTES) {
        return this.fail("patch_line_too_large")
      }
      if (!this.processLine(line)) return this.snapshot(this.issue)
    }

    if (byteLength(this.lineBuffer) > MAX_PATCH_LINE_BYTES) {
      return this.fail("patch_line_too_large")
    }

    return this.snapshot()
  }

  finish(): FableStreamUpdate {
    if (this.closed) return this.closedSnapshot()

    if (this.lineBuffer.trim().length > 0) {
      const lastLine = this.lineBuffer
      this.lineBuffer = ""
      if (!this.processLine(lastLine)) return this.snapshot(this.issue)
    }

    const projected = this.projectPartialSpec(this.compiler.getResult(), false)
    if (projected.issue || !projected.spec) {
      return this.fail(projected.issue ?? "incomplete_tree")
    }

    this.lastValidSpec = projected.spec
    this.closed = true
    this.complete = true
    return this.snapshot(undefined, true)
  }

  cancel(): FableStreamUpdate {
    if (this.closed) return this.closedSnapshot()

    this.lineBuffer = ""
    this.issue = "stream_cancelled"
    this.closed = true
    return this.snapshot(this.issue)
  }

  private processLine(line: string): boolean {
    if (line.trim().length === 0) return true

    let decoded: unknown
    try {
      decoded = JSON.parse(line)
    } catch {
      this.issue = "malformed_patch_json"
      this.closed = true
      return false
    }

    const envelope = patchEnvelopeSchema.safeParse(decoded)
    if (!envelope.success) {
      this.issue = "invalid_patch_envelope"
      this.closed = true
      return false
    }

    const patch = this.validatePatch(envelope.data)
    if (!patch) {
      this.closed = true
      return false
    }

    if (patch.path === "/root" && patch.op === "replace") {
      return this.replaceRoot(patch.value)
    }

    try {
      const compiled = this.compiler.push(`${JSON.stringify(patch)}\n`)
      this.acceptedPatches += compiled.newPatches.length

      const elements = isRecord(compiled.result.elements)
        ? compiled.result.elements
        : {}
      if (Object.keys(elements).length > MAX_ELEMENTS) {
        this.issue = "too_many_elements"
        this.closed = true
        return false
      }

      const projected = this.projectPartialSpec(compiled.result)
      if (projected.issue) {
        this.issue = projected.issue
        this.closed = true
        return false
      }
      if (projected.spec) this.lastValidSpec = projected.spec
      return true
    } catch {
      this.issue = "patch_compile_failed"
      this.closed = true
      return false
    }
  }

  private validatePatch(
    patch: z.infer<typeof patchEnvelopeSchema>
  ): SafePatch | null {
    if (patch.path === "/root") {
      const id = FableIdSchema.safeParse(patch.value)
      if (!id.success) {
        this.issue = "invalid_root_id"
        return null
      }

      const currentRoot = this.compiler.getResult().root
      if (patch.op === "add" && currentRoot !== undefined) {
        this.issue = "duplicate_root_add"
        return null
      }
      if (patch.op === "replace" && currentRoot === undefined) {
        this.issue = "replace_missing_root"
        return null
      }
      return { op: patch.op, path: "/root", value: id.data }
    }

    const match = /^\/elements\/([A-Za-z0-9][A-Za-z0-9_-]{0,63})$/.exec(patch.path)
    if (!match) {
      this.issue = "invalid_patch_path"
      return null
    }

    const id = FableIdSchema.safeParse(match[1])
    const element = FableElementSchema.safeParse(patch.value)
    if (!id.success || !element.success) {
      this.issue = "invalid_component_schema"
      return null
    }

    const elements = this.compiler.getResult().elements
    const existingElements = isRecord(elements) ? elements : {}
    const exists = Object.hasOwn(existingElements, id.data)
    if (patch.op === "add" && exists) {
      this.issue = "duplicate_element_add"
      return null
    }
    if (patch.op === "replace" && !exists) {
      this.issue = "replace_missing_element"
      return null
    }
    if (!exists && Object.keys(existingElements).length >= MAX_ELEMENTS) {
      this.issue = "too_many_elements"
      return null
    }

    return {
      op: patch.op,
      path: `/elements/${id.data}` as `/elements/${string}`,
      value: element.data,
    }
  }

  private replaceRoot(rootId: string): boolean {
    const current = this.compiler.getResult()
    const currentElements = isRecord(current.elements) ? current.elements : {}
    const nextCompiler = createSpecStreamCompiler<CompilerState>({})
    const pending = [rootId]
    const copied = new Set<string>()

    try {
      nextCompiler.push(`${JSON.stringify({ op: "add", path: "/root", value: rootId })}\n`)

      while (pending.length > 0) {
        const id = pending.pop()
        if (!id || copied.has(id) || !Object.hasOwn(currentElements, id)) continue

        const parsed = FableElementSchema.safeParse(currentElements[id])
        if (!parsed.success) {
          this.issue = "invalid_compiled_element"
          this.closed = true
          return false
        }

        copied.add(id)
        nextCompiler.push(
          `${JSON.stringify({ op: "add", path: `/elements/${id}`, value: parsed.data })}\n`
        )
        pending.push(...parsed.data.children)
      }
    } catch {
      this.issue = "patch_compile_failed"
      this.closed = true
      return false
    }

    this.compiler = nextCompiler
    this.acceptedPatches += 1

    const projected = this.projectPartialSpec(this.compiler.getResult())
    if (projected.issue) {
      this.issue = projected.issue
      this.closed = true
      return false
    }
    if (projected.spec) this.lastValidSpec = projected.spec
    return true
  }

  private projectPartialSpec(
    state: CompilerState,
    allowMissingChildren = true
  ): {
    spec: FableViewSpec | null
    issue?: string
  } {
    const rootResult = FableIdSchema.safeParse(state.root)
    if (!rootResult.success || !isRecord(state.elements)) {
      return { spec: null }
    }

    const available = new Map<string, FableElement>()
    for (const [id, value] of Object.entries(state.elements)) {
      const parsedId = FableIdSchema.safeParse(id)
      const parsedElement = FableElementSchema.safeParse(value)
      if (!parsedId.success || !parsedElement.success) {
        return { spec: null, issue: "invalid_compiled_element" }
      }
      available.set(parsedId.data, parsedElement.data)
    }

    // Root swaps can arrive before their replacement element. Keep the last
    // complete snapshot visible until the new root becomes available.
    if (!available.has(rootResult.data)) return { spec: null }

    const visibleElements: Record<string, FableElement> = {}
    const active = new Set<string>()
    const parentCount = new Map<string, number>()
    let issue: string | undefined

    const visit = (id: string, depth: number) => {
      if (issue) return
      if (depth > 6) {
        issue = "maximum_depth_exceeded"
        return
      }
      if (active.has(id)) {
        issue = "cyclic_tree"
        return
      }
      if (Object.hasOwn(visibleElements, id)) return

      const element = available.get(id)
      if (!element) return
      active.add(id)
      const knownChildren = element.children.filter((childId) => available.has(childId))
      if (!allowMissingChildren && knownChildren.length !== element.children.length) {
        issue = "missing_child"
        active.delete(id)
        return
      }
      visibleElements[id] = { ...element, children: knownChildren }

      for (const childId of knownChildren) {
        const nextParentCount = (parentCount.get(childId) ?? 0) + 1
        parentCount.set(childId, nextParentCount)
        if (nextParentCount > 1) {
          issue = "multiple_parents"
          break
        }
        visit(childId, depth + 1)
      }
      active.delete(id)
    }

    visit(rootResult.data, 1)
    if (issue) return { spec: null, issue }

    const validation = validateFableViewSpec({
      root: rootResult.data,
      elements: visibleElements,
    })
    if (!validation.success) return { spec: null, issue: validation.issues[0] }
    return { spec: validation.data }
  }

  private fail(issue: string): FableStreamUpdate {
    this.issue = issue
    this.closed = true
    return this.snapshot(issue)
  }

  private closedSnapshot(): FableStreamUpdate {
    return this.snapshot(
      this.issue ?? (this.complete ? undefined : "stream_closed"),
      this.complete
    )
  }

  private snapshot(issue?: string, complete = false): FableStreamUpdate {
    return {
      spec: this.lastValidSpec,
      acceptedPatches: this.acceptedPatches,
      complete,
      ...(issue ? { issue } : {}),
    }
  }
}

export function createFableSpecStream(): FableSpecStream {
  return new FableSpecStream()
}

export function encodeFableSpecStream(spec: FableViewSpec): string {
  const validation = validateFableViewSpec(spec)
  if (!validation.success) {
    throw new Error(`Cannot encode invalid Fable spec: ${validation.issues[0]}`)
  }

  const patches = [
    { op: "add", path: "/root", value: validation.data.root },
    ...Object.entries(validation.data.elements).map(([id, element]) => ({
      op: "add",
      path: `/elements/${id}`,
      value: element,
    })),
  ]
  return `${patches.map((patch) => JSON.stringify(patch)).join("\n")}\n`
}

"use client"

import { useState } from "react"

import { FableBarChart } from "@/components/fable-ui/v2/chart"
import {
  FableAssetCatalogSchema,
  FableLinkCatalogSchema,
  FableViewDataSchema,
  validateFableViewSpec,
  type FableElement,
  type FableFilterResult,
} from "./catalog"
import { FableEntityCard } from "@/components/fable-ui/v2/entity-card"
import { FableFilterBar } from "@/components/fable-ui/v2/filter-bar"
import { FableMediaImage } from "@/components/fable-ui/v2/media-image"
import { FableMetricCard } from "@/components/fable-ui/v2/metric-card"
import {
  FableGrid,
  Section,
  Stack,
  Surface,
} from "@/components/fable-ui/v2/layout"
import {
  FableRichText,
  FableTypography,
} from "@/components/fable-ui/v2/typography"
import { FableRichContent } from "@/components/fable-ui/v2/rich-content"
import { cn } from "@/lib/utils"

export interface FableSpecRendererProps {
  /** Model-facing JSON is validated again before any element can render. */
  spec: unknown
  /** Values come from the host, keyed by IDs the host has authorized. */
  data: unknown
  /** Local, host-curated image paths. Remote and protocol-relative paths fail closed. */
  assets?: unknown
  /** Host-authorized link destinations and their visible labels. */
  links?: unknown
  className?: string
}

function Unavailable({ label }: { label: string }) {
  return (
    <p
      role="status"
      className="rounded-xl border border-dashed border-border px-3 py-3 text-sm text-muted-foreground"
    >
      {label} is unavailable.
    </p>
  )
}

function filterSelection(
  filter: FableFilterResult,
  currentValue: string | undefined
) {
  const allowedValues = new Set(filter.options.map((option) => option.value))
  return currentValue && allowedValues.has(currentValue)
    ? currentValue
    : filter.allValue
}

export function FableSpecRenderer({
  spec,
  data,
  assets,
  links,
  className,
}: FableSpecRendererProps) {
  const [filterValues, setFilterValues] = useState<Record<string, string>>({})
  const parsedSpec = validateFableViewSpec(spec)
  const parsedData = FableViewDataSchema.safeParse(data)
  const parsedAssets = FableAssetCatalogSchema.safeParse(assets ?? {})
  const parsedLinks = FableLinkCatalogSchema.safeParse(links ?? {})

  if (!parsedSpec.success) {
    return (
      <div
        role="status"
        data-fable-ui-error="invalid-spec"
        className={cn(
          "rounded-2xl border border-dashed border-border p-5 text-sm text-muted-foreground",
          className
        )}
      >
        This response layout could not be displayed safely.
      </div>
    )
  }

  if (!parsedData.success) {
    return (
      <div
        role="status"
        data-fable-ui-error="invalid-data"
        className={cn(
          "rounded-2xl border border-dashed border-border p-5 text-sm text-muted-foreground",
          className
        )}
      >
        Supporting data is unavailable.
      </div>
    )
  }

  const specValue = parsedSpec.data
  const dataValue = parsedData.data
  const assetValue = parsedAssets.success ? parsedAssets.data : {}
  const linkValue = parsedLinks.success ? parsedLinks.data : {}

  const renderNode = (id: string, depth = 0): React.ReactNode => {
    if (depth > 6 || !Object.hasOwn(specValue.elements, id)) return null
    const element: FableElement = specValue.elements[id]

    switch (element.type) {
      case "Text": {
        const as = element.props.level === "heading" ? "h2" : "p"
        return (
          <FableTypography key={id} as={as} level={element.props.level}>
            {element.props.content}
          </FableTypography>
        )
      }
      case "RichText":
        return <FableRichText key={id} spans={element.props.spans} />
      case "RichContent":
        return (
          <FableRichContent
            key={id}
            blocks={element.props.blocks}
            links={linkValue}
          />
        )
      case "Metric": {
        const result = Object.hasOwn(dataValue, element.props.resultId)
          ? dataValue[element.props.resultId]
          : undefined
        if (!result || result.kind !== "metric") {
          return <Unavailable key={id} label="Metric data" />
        }
        return (
          <FableMetricCard
            key={id}
            label={result.label}
            value={result.value}
            format={result.format}
            currency={result.currency}
            unit={result.unit}
            locale={result.locale}
          />
        )
      }
      case "EntityList": {
        const result = Object.hasOwn(dataValue, element.props.resultId)
          ? dataValue[element.props.resultId]
          : undefined
        if (!result || result.kind !== "entity-list") {
          return <Unavailable key={id} label="Entity data" />
        }

        const filterResult = element.props.filterId
          ? dataValue[element.props.filterId]
          : undefined
        if (element.props.filterId && filterResult?.kind !== "filter") {
          return <Unavailable key={id} label="Filter data" />
        }

        const currentFilter =
          filterResult?.kind === "filter"
            ? filterSelection(
                filterResult,
                filterValues[element.props.filterId ?? ""]
              )
            : undefined
        const allFilterValue =
          filterResult?.kind === "filter" ? filterResult.allValue : undefined
        const items = result.items.filter((item) => {
          if (!element.props.filterId || currentFilter === allFilterValue)
            return true
          return item.filterValues?.[element.props.filterId] === currentFilter
        })

        return (
          <section
            key={id}
            aria-label={result.label}
            className="min-w-0 space-y-3"
          >
            <FableTypography
              as="h3"
              level="heading"
              className="text-base sm:text-lg"
            >
              {result.label}
            </FableTypography>
            {items.length > 0 ? (
              <FableGrid columns={3} gap={3}>
                {items.map((item) => (
                  <FableEntityCard
                    key={item.id}
                    name={item.name}
                    location={item.location}
                    description={item.description}
                    value={item.value}
                    unit={item.unit}
                    locale={result.locale}
                    changePercent={item.changePercent}
                    valueLabel={result.valueLabel ?? "Value"}
                  />
                ))}
              </FableGrid>
            ) : (
              <p
                role="status"
                className="rounded-xl bg-muted/50 px-4 py-5 text-sm text-muted-foreground"
              >
                No items match this filter.
              </p>
            )}
          </section>
        )
      }
      case "Chart": {
        const result = Object.hasOwn(dataValue, element.props.resultId)
          ? dataValue[element.props.resultId]
          : undefined
        if (!result || result.kind !== "chart") {
          return <Unavailable key={id} label="Chart data" />
        }
        return (
          <FableBarChart
            key={id}
            label={result.label}
            points={result.points}
            format={result.format}
            currency={result.currency}
            locale={result.locale}
          />
        )
      }
      case "Filter": {
        const result = Object.hasOwn(dataValue, element.props.filterId)
          ? dataValue[element.props.filterId]
          : undefined
        if (!result || result.kind !== "filter") {
          return <Unavailable key={id} label="Filter options" />
        }
        const currentValue = filterSelection(
          result,
          filterValues[element.props.filterId]
        )
        return (
          <FableFilterBar
            key={id}
            label={result.label}
            options={result.options}
            value={currentValue}
            onValueChange={(value) => {
              if (result.options.some((option) => option.value === value)) {
                setFilterValues((current) => ({
                  ...current,
                  [element.props.filterId]: value,
                }))
              }
            }}
          />
        )
      }
      case "Media": {
        const src = Object.hasOwn(assetValue, element.props.assetId)
          ? assetValue[element.props.assetId]
          : undefined
        if (!src) return <Unavailable key={id} label="Image" />
        return (
          <FableMediaImage
            key={id}
            src={src.src}
            alt={src.alt}
            decorative={src.decorative}
          />
        )
      }
      case "Stack": {
        const children = element.children.map((childId) =>
          renderNode(childId, depth + 1)
        )
        return (
          <Stack
            key={id}
            direction={element.props.direction}
            gap={element.props.gap}
          >
            {children}
          </Stack>
        )
      }
      case "Grid":
        return (
          <FableGrid
            key={id}
            gap={element.props.gap}
            columns={element.props.columns}
          >
            {element.children.map((childId) => renderNode(childId, depth + 1))}
          </FableGrid>
        )
      case "Section":
        return (
          <Section
            key={id}
            gap={element.props.gap}
            aria-label={element.props.title}
          >
            {element.props.title ? (
              <FableTypography
                as="h3"
                level="heading"
                className="text-base sm:text-lg"
              >
                {element.props.title}
              </FableTypography>
            ) : null}
            {element.children.map((childId) => renderNode(childId, depth + 1))}
          </Section>
        )
      case "Surface":
        return (
          <Surface
            key={id}
            variant={element.props.variant}
            padding={element.props.padding}
          >
            {element.children.map((childId) => renderNode(childId, depth + 1))}
          </Surface>
        )
      default:
        return null
    }
  }

  return (
    <div data-fable-ui="v2-renderer" className={cn("min-w-0", className)}>
      {renderNode(specValue.root)}
    </div>
  )
}
